import { describe, expect, test } from "bun:test";
import type { GetOnlineEvaluationConfigResponse } from "@aws-sdk/client-bedrock-agentcore-control";
import {
  createSilentLogger,
  TestCoreClient,
  TestGlobalConfigAccessor,
  testIO,
} from "../../../testing";
import { createRootHandler } from "../../index";

const ID = "checkout_oec-a1b2c3d4e5";
const NOTE =
  "note: Insights generated by Builtin.FailureAnalysis are not in this output.\n" +
  "      Run: agentcore eval insight list --application-name checkout.DEFAULT";

function config(overrides: Partial<GetOnlineEvaluationConfigResponse> = {}) {
  return {
    onlineEvaluationConfigId: ID,
    evaluators: [{ evaluatorId: "Builtin.FailureAnalysis" }],
    dataSourceConfig: {
      cloudWatchLogs: { logGroupNames: ["/aws/agent"], serviceNames: ["checkout.DEFAULT"] },
    },
    ...overrides,
  } as unknown as GetOnlineEvaluationConfigResponse;
}

async function run(core: TestCoreClient, args: string[]) {
  const io = testIO();
  const root = createRootHandler(core, {
    io: io.io,
    logger: createSilentLogger(),
    globalConfigAccessor: new TestGlobalConfigAccessor(),
  });
  await root.route(["node", "agentcore", "eval", "online-eval", ...args, "--region", "us-west-2"]);
  return io;
}

const getCalls = (core: TestCoreClient) =>
  core.eval.calls.filter((c) => c.method === "getOnlineEvaluationConfig");

describe("online-eval Insights note", () => {
  test("create looks the config up only when FailureAnalysis is among the evaluators", async () => {
    const core = new TestCoreClient();
    core.eval.setOnlineEvalCreateResponse({ onlineEvaluationConfigId: ID } as never);
    core.eval.setOnlineEvalGetResponse(config());
    const base = ["create", "--name", "checkout_oec", "--agent", "rt-1", "--sampling-rate", "10"];
    const evaluators = (id: string) => [...base, "--evaluators", id];

    const without = await run(core, evaluators("Builtin.Helpfulness"));
    expect(getCalls(core)).toEqual([]);
    expect(without.stderr()).toBe("");

    const withFa = await run(core, evaluators("Builtin.FailureAnalysis"));
    expect(withFa.stderr()).toBe(NOTE);
  });

  test.each<[string, string[]]>([
    ["get", ["get", "--id", ID]],
    ["update", ["update", "--id", ID, "--description", "new"]],
    ["logs", ["logs", "--id", ID]],
  ])("%s prints no note", async (_, args) => {
    const core = new TestCoreClient();
    core.eval.setOnlineEvalGetResponse(config());
    const io = await run(core, args);
    expect(io.stderr()).not.toContain("Insights");
  });
});
